var n=`0767-mchuzi-wa-samaki`;var t=`world-0767`;var a=`TZ`;var s=`eastern-africa`;var o=4;var r=40;var g={en:`Mchuzi wa Samaki`,ua:`Мчузі ва самакі`};var l={en:`Mchuzi wa Samaki is a Tanzania classic prepared with yellow onion, tomato, garlic, tilapia. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мчузі ва самакі, страва кухні країни Танзанія зі складниками: жовта цибуля, помідор, часник, тилапія. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,180,`g`],[`tomato`,360,`g`],[`garlic`,4,`clove`],[`sunflower-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 26 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 26 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:26,i:[[`tilapia`,780,`g`],[`coconut-milk`,410,`ml`],[`ground-turmeric`,4,`g`],[`ginger-root`,25,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lemon-juice`,30,`ml`],[`cilantro`,20,`g`]]}];var u={slug:n,id:t,country:`TZ`,region:s,servings:4,minutes:40,title:g,text:l,steps:m};export{a as country,u as default,t as id,r as minutes,s as region,o as servings,n as slug,m as steps,l as text,g as title};